// Accept API response { leads: [...] } or one item per lead
const first = $input.first().json;
let leads = [];
if (Array.isArray(first.leads)) {
  leads = first.leads;
} else if (first.practice || first.email) {
  leads = $input.all().map((i) => i.json);
} else {
  leads = [first];
}

const STAGE_ALIASES = {
  no_reply: 'first_email_sent',
  follow_up_interested: 'interested',
  follow_up_not_interested: 'not_interested',
  contacted: 'first_email_sent',
};

const output = [];
for (const item of leads) {
  const p = item.practice || item;
  const email = (p.email || item.email || '').trim();
  if (!email) continue;
  const contact = (p.contact || p.name || '').trim();
  const firstWord =
    contact.split(/\s+/)[0] ||
    (p.name || '').split(/\s+/)[0] ||
    'there';
  const web = p.website || item.website || 'https://dimensiongroupglobal.com';
  let stage = String(item.outreach_stage || p.outreach_stage || 'cold').trim();
  stage = STAGE_ALIASES[stage] || stage;
  output.push({
    json: {
      email,
      firstName: firstWord,
      companyName: p.name || item.name || 'your practice',
      website: web,
      websiteLink: web.replace(/^https?:\/\//, ''),
      outreach_stage: stage,
      practice_id: p.id || item.practice_id || item.slug,
      lead_id: item.lead_id || p.url || item.url,
      country: p.country || item.country || null,
    },
  });
}
return output;
